"use client";

import { loadFont } from "@remotion/google-fonts/Gabarito";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type CrewOfOneElementId,
  crewOfOneTimeline,
  DEFAULT_ROLES,
  rolesOf,
} from "./timeline";

const gabarito = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface CrewOfOneProps {
  roles?: string[];
  name?: string;
  accent?: string;
  /** Text color of the roles; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the roles and name. Load it yourself; Gabarito by default. */
  fontFamily?: string;
  /** Weight of the roles. */
  fontWeight?: number;
  /** Size of the name relative to the roles. */
  nameScale?: number;
  /** Size of the credits, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the roll, its steps, the name and the gather,
   * by the ids in `./timeline`. Frames on the scene timeline, after `delay`
   * and `speed`.
   */
  timing?: Timing<CrewOfOneElementId>;
}

const THEMES = {
  dark: { bg: "#3B1E6E", ink: "#FFFFFF", accent: "#FF7A6B" },
  light: { bg: "#EDE7FB", ink: "#3B1E6E", accent: "#D9483A" },
} as const;

const ROLE_W = 400;
const NAME_W = 500;
const TRACK = -0.02;
const NAME_TRACK = -0.03;
const FONT_PX = 200;
const NAME_SCALE = 2.3;
const LINE = 1.32;
const STACK_LINE = 1.06;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const midway = (q: number) => q > 5e-4 && q < 1 - 5e-4;

interface Metrics {
  roles: number;
  name: number;
  asc: number;
  desc: number;
}

function measure(
  roles: string[],
  name: string,
  family: string,
  roleWeight: number,
): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("crew-of-one: no 2d context");
  ctx.font = `${roleWeight} ${FONT_PX}px "${family}"`;
  let widest = 0.1;
  for (const r of roles) {
    widest = Math.max(
      widest,
      ctx.measureText(r).width / FONT_PX + TRACK * Array.from(r).length,
    );
  }
  const fm = ctx.measureText("Hxg");
  ctx.font = `${NAME_W} ${FONT_PX}px "${family}"`;
  const nameW =
    ctx.measureText(name).width / FONT_PX +
    NAME_TRACK * Array.from(name).length;
  return {
    roles: widest,
    name: nameW,
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
  };
}

function useMetrics(
  roles: string[],
  name: string,
  family: string,
  roleWeight: number,
) {
  const key = [name, ...roles].join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("crew-of-one: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      gabarito.waitUntilDone(),
      document.fonts.load(`${roleWeight} 100px "${family}"`),
      document.fonts.load(`${NAME_W} 100px "${family}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const [n, ...rs] = key.split("\u0001");
        setState({ key, m: measure(rs, n, family, roleWeight) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, family, roleWeight]);
  return state && state.key === key ? state.m : null;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function CrewOfOne(props: CrewOfOneProps) {
  const {
    roles = DEFAULT_ROLES,
    name = "you",
    accent,
    ink,
    background,
    fontFamily = gabarito.fontFamily,
    fontWeight = ROLE_W,
    nameScale = NAME_SCALE,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay);
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  // The roll stretches to 60% of the clip length, without `speed`.
  const tl = useTimeline(crewOfOneTimeline, props, durationInFrames, timing);
  const t = frame * speed;
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const list = rolesOf(roles);
  const m = useMetrics(list, name, fontFamily, fontWeight);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.07 : 0.06);
  const gap = W * (portrait ? 0.035 : 0.025);
  const gutter = W * (portrait ? 0.56 : 0.54);
  const leftRoom = gutter - gap / 2 - margin;
  const rightRoom = W - margin - (gutter + gap / 2);
  const stackFit = (H * 0.86) / (n * STACK_LINE);
  const F = Math.min(
    H * (portrait ? 0.055 : 0.13),
    leftRoom / m.roles,
    rightRoom / (m.name * nameScale),
    stackFit,
  );
  const NF = F * nameScale;
  const mid = H / 2;
  const baseline = mid + F * 0.36;
  const top = (base: number, size: number) =>
    base - ((1 - m.asc - m.desc) / 2 + m.asc) * size;

  const introEl = tl.get("intro");
  const gatherEl = tl.get("gather");
  const rolls = tl.lane("Roll").filter((e) => e.id.startsWith("roll:"));
  const drivers = (tt: number) => {
    let p = 0;
    for (const roll of rolls) {
      p += interpolate(tt, [roll.start, roll.end], [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      });
    }
    const gather = interpolate(tt, [gatherEl.start, gatherEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    const intro = interpolate(tt, [introEl.start, introEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    return { p, gather, intro };
  };
  const { p, gather, intro } = drivers(t);
  const before = drivers((frame - 1) * speed);
  const after = drivers((frame + 1) * speed);
  const nameEl = tl.get("name");
  const nameIn = interpolate(t, [nameEl.start, nameEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const LS = F * LINE;
  const LS2 = F * STACK_LINE;
  const stackTop = -((n - 1) / 2) * LS2;

  const roleStyle: React.CSSProperties = {
    position: "absolute",
    right: W - (gutter - gap / 2),
    height: F,
    lineHeight: `${F}px`,
    whiteSpace: "pre",
    fontFamily,
    fontWeight,
    fontSize: F,
    letterSpacing: `${TRACK}em`,
    color: fg,
    textAlign: "right",
  };

  const rowY = (i: number, q: ReturnType<typeof drivers>) => {
    const rollY = (i - q.p) * LS + (1 - q.intro) * LS * 0.9;
    const stackY = stackTop + i * LS2;
    return rollY + (stackY - rollY) * q.gather;
  };

  const nodes: React.ReactNode[] = list.map((r, i) => {
    const d = i - p;
    const y = rowY(i, { p, gather, intro });
    const stackY = stackTop + i * LS2;
    // Layout rounds a box and a baseline to whole pixels, so a row eased by
    // `top` clicks along pixel by pixel. It is laid out in its stack slot,
    // where it ends up, and gets everywhere else by a transform. One layout
    // position for its whole life: handing a row from the transform back to
    // layout at each hold would jump it by what layout rounds off.
    const moving =
      Math.abs(rowY(i, after) - y) > 1e-3 ||
      Math.abs(y - rowY(i, before)) > 1e-3;
    const ad = Math.abs(d);
    const rollA =
      interpolate(ad, [0, 0.55, 1, 2.6], [1, 0.42, 0.3, 0], CLAMP) * intro;
    const a = rollA + (1 - rollA) * gather;
    return (
      <div
        key={`r${i}`}
        style={{
          ...roleStyle,
          top: top(baseline + stackY, F),
          transform: `translateY(${y - stackY}px)${glide(moving)}`,
          opacity: a,
        }}
      >
        {r}
      </div>
    );
  });

  const nameTop = top(baseline, NF);
  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        {nodes}
        <div
          style={{
            position: "absolute",
            left: gutter + gap / 2,
            top: nameTop - NF * 0.15,
            height: NF * 1.35,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "relative",
              top: NF * 0.15,
              height: NF,
              lineHeight: `${NF}px`,
              whiteSpace: "pre",
              fontFamily,
              fontWeight: NAME_W,
              fontSize: NF,
              letterSpacing: `${NAME_TRACK}em`,
              color: hi,
              transform: `translateY(${((1 - nameIn) * NF * 1.3).toFixed(2)}px)${glide(midway(nameIn))}`,
            }}
          >
            {name}
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The roll of credits rising in, the name sliding up beside it, each step of
// the roll onto the next role, and the roles gathering into a stack. Frames
// on the 30 fps scene timeline, after `delay` and `speed`. The ids are
// public: a saved `timing` prop refers to them.

export type CrewOfOneElementId = "intro" | "name" | `roll:${number}` | "gather";

export interface CrewOfOneTimingProps {
  roles?: string[];
}

export const DEFAULT_ROLES = [
  "Written by",
  "Directed by",
  "Edited by",
  "Motion by",
  "Captions by",
  "Shipped by",
];

/** The roles drawn: the list, or one placeholder when it is empty. */
export const rolesOf = (roles: string[]) =>
  roles.length > 0 ? roles : ["Made by"];

const INTRO_END = 18;
const NAME_AT = 8;
const NAME_END = 26;
const ROLL_START = 30;
const GATHER_GAP = 12;
const GATHER = 24;

// `length` is the clip length without `speed`: the roll stretches to 60% of
// it. Each step of the roll follows the one before; the gather follows the
// last step.
export const crewOfOneTimeline = defineTimeline<
  CrewOfOneElementId,
  CrewOfOneTimingProps
>(({ roles = DEFAULT_ROLES }, { length }) => {
  const n = rolesOf(roles).length;
  const D = Math.max(90, length);
  const rollEnd = Math.max(ROLL_START + (n - 1) * 10, D * 0.6);
  const step = n > 1 ? (rollEnd - ROLL_START) / (n - 1) : 1;
  const move = Math.min(13, step * 0.55);
  const cStart = rollEnd + GATHER_GAP;
  const elements: TimelineElement<CrewOfOneElementId>[] = [
    {
      id: "intro",
      lane: "Roll",
      label: "roll in",
      start: 0,
      length: INTRO_END,
    },
    {
      id: "name",
      lane: "Name",
      label: "name",
      start: NAME_AT,
      length: NAME_END - NAME_AT,
    },
  ];
  for (let k = 1; k < n; k++) {
    elements.push({
      id: `roll:${k}`,
      lane: "Roll",
      label: rolesOf(roles)[k],
      start: ROLL_START + (k - 1) * step + (step - move),
      length: move,
      follows: k > 1 ? `roll:${k - 1}` : undefined,
    });
  }
  elements.push({
    id: "gather",
    lane: "Roll",
    label: "stack",
    start: cStart,
    length: GATHER,
    follows: n > 1 ? `roll:${n - 1}` : undefined,
  });
  return elements;
});
